WHERE status != 'DELETED'

  AND status = #{status}


  AND receive_start_at >= #{receiveStartAtFrom}


  AND receive_end_at <= #{receiveEndAtTo}

ORDER BY updated_at DESC, created_at DESC
LIMIT #{pageSize} OFFSET #{offset}

